package com.example.praticum.data.export;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;
/** Écrit un classeur Excel OOXML autonome pour une feuille de présence. */
public final class AttendanceExcelExporter{
 private AttendanceExcelExporter(){}
 public static final class StudentLine{
  public final int order;public final String matricule,lastName,firstName,lastNameArabic,firstNameArabic,status;
  public StudentLine(int order,String matricule,String lastName,String firstName,String lastNameArabic,String firstNameArabic,String status){this.order=order;this.matricule=s(matricule);this.lastName=s(lastName);this.firstName=s(firstName);this.lastNameArabic=s(lastNameArabic);this.firstNameArabic=s(firstNameArabic);this.status=s(status);}
 }
 public static final class Data{
  public final String session,group,groupCode,specialty,level,academicYear,date,start,end,room;public final List<StudentLine> students;
  public Data(String session,String group,String groupCode,String specialty,String level,String academicYear,String date,String start,String end,String room,List<StudentLine> students){this.session=s(session);this.group=s(group);this.groupCode=s(groupCode);this.specialty=s(specialty);this.level=s(level);this.academicYear=s(academicYear);this.date=s(date);this.start=s(start);this.end=s(end);this.room=s(room);this.students=new ArrayList<>(students);}
 }
 public static void write(OutputStream output,Data d)throws IOException{
  int present=0,absent=0,late=0,unreported=0;for(StudentLine x:d.students){if("Présent".equals(x.status))present++;else if("Absent".equals(x.status))absent++;else if("En retard".equals(x.status))late++;else unreported++;}
  StringBuilder rows=new StringBuilder();rows.append(row(1,cell("A1","FEUILLE DE PRÉSENCE",1)));String[][] meta={{"Séance",d.session},{"Groupe",d.groupCode.isEmpty()?d.group:d.groupCode+" — "+d.group},{"Spécialité",d.specialty},{"Niveau",d.level},{"Année universitaire",d.academicYear},{"Date",d.date},{"Horaire",joinTime(d.start,d.end)},{"Salle",d.room},{"Effectif",String.valueOf(d.students.size())}};
  for(int i=0;i<meta.length;i++)rows.append(row(i+2,cell("A"+(i+2),meta[i][0],2)+cell("B"+(i+2),meta[i][1],4)));
  rows.append(row(11,cell("A11","Présents",2)+cell("B11",String.valueOf(present),4)+cell("C11","Absents",2)+cell("D11",String.valueOf(absent),4)+cell("E11","En retard",2)+cell("F11",String.valueOf(late),4)+cell("G11","Non renseignés",2)+cell("H11",String.valueOf(unreported),4)));
  rows.append("<row r=\"12\"/>");
  String[] headers={"N° groupe","Matricule","Nom","Prénom","Nom arabe","Prénom arabe","Statut de présence"};StringBuilder header=new StringBuilder();for(int c=0;c<headers.length;c++)header.append(cell(col(c)+"13",headers[c],3));rows.append(row(13,header.toString()));
  for(int i=0;i<d.students.size();i++){StudentLine x=d.students.get(i);int r=i+14,style=(i%2==0)?4:5;String[] v={String.valueOf(x.order),x.matricule,x.lastName,x.firstName,x.lastNameArabic,x.firstNameArabic,x.status.isEmpty()?"Non renseigné":x.status};StringBuilder line=new StringBuilder();for(int c=0;c<v.length;c++)line.append(cell(col(c)+r,v[c],style));rows.append(row(r,line.toString()));}
  int endRow=Math.max(14,d.students.size()+13);
  String sheet="<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"13\" topLeftCell=\"A14\" activePane=\"bottomLeft\" state=\"frozen\"/><selection pane=\"bottomLeft\" activeCell=\"A14\" sqref=\"A14\"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight=\"21\"/><cols><col min=\"1\" max=\"1\" width=\"14\" customWidth=\"1\"/><col min=\"2\" max=\"2\" width=\"18\" customWidth=\"1\"/><col min=\"3\" max=\"4\" width=\"22\" customWidth=\"1\"/><col min=\"5\" max=\"6\" width=\"22\" customWidth=\"1\"/><col min=\"7\" max=\"7\" width=\"24\" customWidth=\"1\"/><col min=\"8\" max=\"8\" width=\"16\" customWidth=\"1\"/></cols><sheetData>"+rows+"</sheetData><autoFilter ref=\"A13:G"+endRow+"\"/><mergeCells count=\"10\"><mergeCell ref=\"A1:H1\"/><mergeCell ref=\"B2:H2\"/><mergeCell ref=\"B3:H3\"/><mergeCell ref=\"B4:H4\"/><mergeCell ref=\"B5:H5\"/><mergeCell ref=\"B6:H6\"/><mergeCell ref=\"B7:H7\"/><mergeCell ref=\"B8:H8\"/><mergeCell ref=\"B9:H9\"/><mergeCell ref=\"B10:H10\"/></mergeCells></worksheet>";
  try(ZipOutputStream z=new ZipOutputStream(output,StandardCharsets.UTF_8)){put(z,"[Content_Types].xml","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/></Types>");
   put(z,"_rels/.rels","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
   put(z,"xl/workbook.xml","<?xml version=\"1.0\" encoding=\"UTF-8\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Présences\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");
   put(z,"xl/_rels/workbook.xml.rels","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/><Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");
   put(z,"xl/styles.xml",styles());put(z,"xl/worksheets/sheet1.xml",sheet);
  }
 }
 private static String styles(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><fonts count=\"4\"><font><sz val=\"11\"/><name val=\"Calibri\"/></font><font><b/><color rgb=\"FFFFFFFF\"/><sz val=\"11\"/><name val=\"Calibri\"/></font><font><b/><color rgb=\"FFFFFFFF\"/><sz val=\"16\"/><name val=\"Calibri\"/></font><font><b/><color rgb=\"FF17365D\"/><sz val=\"11\"/><name val=\"Calibri\"/></font></fonts><fills count=\"5\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF17365D\"/><bgColor indexed=\"64\"/></patternFill></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FFDCE6F1\"/><bgColor indexed=\"64\"/></patternFill></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FFF3F6FA\"/><bgColor indexed=\"64\"/></patternFill></fill></fills><borders count=\"2\"><border><left/><right/><top/><bottom/><diagonal/></border><border><left style=\"thin\"><color rgb=\"FFD9E2F3\"/></left><right style=\"thin\"><color rgb=\"FFD9E2F3\"/></right><top style=\"thin\"><color rgb=\"FFD9E2F3\"/></top><bottom style=\"thin\"><color rgb=\"FFD9E2F3\"/></bottom><diagonal/></border></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"6\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/><xf numFmtId=\"0\" fontId=\"2\" fillId=\"2\" borderId=\"1\" applyFont=\"1\" applyFill=\"1\" applyBorder=\"1\" applyAlignment=\"1\"><alignment vertical=\"center\"/></xf><xf numFmtId=\"0\" fontId=\"3\" fillId=\"3\" borderId=\"1\" applyFont=\"1\" applyFill=\"1\" applyBorder=\"1\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"2\" borderId=\"1\" applyFont=\"1\" applyFill=\"1\" applyBorder=\"1\" applyAlignment=\"1\"><alignment horizontal=\"center\" vertical=\"center\" wrapText=\"1\"/></xf><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"1\" applyBorder=\"1\"/><xf numFmtId=\"0\" fontId=\"0\" fillId=\"4\" borderId=\"1\" applyFill=\"1\" applyBorder=\"1\"/></cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>";}
 private static String row(int n,String cells){return "<row r=\""+n+"\" customHeight=\"1\" ht=\"21\">"+cells+"</row>";}
 private static String cell(String ref,String text,int style){return "<c r=\""+ref+"\" s=\""+style+"\" t=\"inlineStr\"><is><t xml:space=\"preserve\">"+xml(text)+"</t></is></c>";}
 private static String xml(String s){return s(s).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}
 private static String col(int n){StringBuilder s=new StringBuilder();while(n>=0){s.insert(0,(char)('A'+n%26));n=n/26-1;}return s.toString();}
 private static String joinTime(String a,String b){if(a.isEmpty())return b;if(b.isEmpty())return a;return a+" – "+b;}
 private static String s(String x){return x==null?"":x;}
 private static void put(ZipOutputStream z,String name,String value)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(value.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
}